function CROSSING-BUDGET-ACCUMULATION(n, drop):
    require n >= 2
    if drop <= 0: return 0
    S <- drop * n * (n^2 - 1) / 24          # exact rational
    k <- integer_sqrt(floor(S))
    while k^2 < S: k <- k + 1               # exact ceiling of sqrt(S)
    return k

function BEST-BUDGET-FROM-IDENTITY(n, target_rho):
    drop <- 1 - target_rho
    a <- CROSSING-BUDGET-SINGLE-STEP(n, drop)
    b <- CROSSING-BUDGET-ACCUMULATION(n, drop)
    return (a, b, max(a, b))

function KENDALL-DESCENT(n, target):
    sigma <- [0, 1, ..., n-1]          # identity ranking, rho = +1
    D <- 0                             # squared displacement sum
    moves <- empty list
    while 1 - 6D / (n(n^2 - 1)) > target:
        best_i <- -1;  best_gain <- 0
        for i in 0 .. n-2:
            gain <- 2 * (sigma[i+1] - sigma[i])   # exact identity
            if gain > best_gain: best_i <- i; best_gain <- gain
        if best_i < 0: break            # reversal reached, no descent left
        swap sigma[best_i], sigma[best_i + 1]
        D <- D + best_gain
        append best_i to moves
    return sigma, moves, 1 - 6D / (n(n^2 - 1))

function VERIFY-LIPSCHITZ(n, moves, rho):
    return |1 - rho| <= 12 * length(moves) / (n(n+1))

