"""Algorithm: incremental Kendall descent of a rank correlation."""

from __future__ import annotations

from fractions import Fraction
from typing import List, Tuple


def spearman_from_displacement(n: int, d: int) -> Fraction:
    """rho = 1 - 6 D / (n(n^2 - 1)), exact."""
    return Fraction(1) - Fraction(6 * d, n * (n * n - 1))


def kendall_descent(n: int, target: Fraction) -> Tuple[List[int], List[int], Fraction]:
    """Greedily drive rho from +1 down to at most `target` by adjacent swaps.

    The displacement sum is maintained incrementally: swapping the values at
    positions i and i+1 changes it by exactly 2*(sigma[i+1] - sigma[i]).  This is
    an identity, so no recomputation of the sum is ever required.

    Returns the final ranking, the list of swap positions, and the final rho.
    Complexity: O(1) per update, O(n) per greedy selection, O(nK) overall.
    """
    if n < 2:
        raise ValueError("n must be at least 2")
    sigma: List[int] = list(range(n))
    moves: List[int] = []
    d = 0
    while spearman_from_displacement(n, d) > target:
        best_i, best_gain = -1, 0
        for i in range(n - 1):
            gain = 2 * (sigma[i + 1] - sigma[i])
            if gain > best_gain:
                best_i, best_gain = i, gain
        if best_i < 0:
            break  # no improving swap: the reversal has been reached
        sigma[best_i], sigma[best_i + 1] = sigma[best_i + 1], sigma[best_i]
        d += best_gain
        moves.append(best_i)
    return sigma, moves, spearman_from_displacement(n, d)


def verify_lipschitz(n: int, moves: List[int], final_rho: Fraction) -> bool:
    """Check the chain against the Lipschitz law |delta rho| <= 12 K /(n(n+1))."""
    return abs(Fraction(1) - final_rho) <= Fraction(12 * len(moves), n * (n + 1))


if __name__ == "__main__":
    sigma, moves, rho = kendall_descent(60, Fraction(558, 1000))
    print(f"reached rho = {float(rho):.6f} in {len(moves)} adjacent swaps")
    print("Lipschitz law respected:", verify_lipschitz(60, moves, rho))

